// Logical coordinates stay compatible with existing Firestore garden records.
export const WORLD_WIDTH=1280,WORLD_HEIGHT=736;
export function ground(x,y){return {x:72+x*48+y*16,y:112+y*40};}
export function depth(x,y){return ground(x,y).y*2+x;}
export function groundStyle(x,y,width=96,height=96){const p=ground(x,y);return `left:${p.x-width/2}px;top:${p.y-height}px;z-index:${depth(x,y)}`;}
export function gardenScenery(){
 const trees=Array.from({length:12},(_,i)=>`<use href="#garden-tree" x="${i*112-20}" y="${i%3*12-28}"/>`).join('');
 const tufts=Array.from({length:160},(_,i)=>{const x=32+(i*197)%1216,y=100+(i*137)%556;return `<path fill="${i%3?'#90bb69':'#b7d58b'}" d="M${x} ${y}h4v-4h4v8h-8zm12 4h4v4h-4z"/>`}).join('');
 const stones=Array.from({length:18},(_,i)=>{const y=260+i*24,x=944-Math.round(i*22+Math.sin(i*.5)*38);return `<path fill="${i%2?'#e3d5ae':'#d4c9a3'}" stroke="#b5b18a" stroke-width="2" d="M${x} ${y}h44l16 10-8 10h-48l-12-10z"/>`}).join('');
 return `<svg class="garden-scenery" viewBox="0 0 1280 736" aria-hidden="true" shape-rendering="crispEdges"><defs><g id="garden-tree"><path fill="#649357" opacity=".4" d="M12 110h92v12H12z"/><path fill="#78573b" d="M48 60h20v58H48z"/><path fill="#b58954" d="M48 64h8v48h-8z"/><path fill="#346d48" d="M8 40h12V20h20V8h40v12h20v20h12v48H92v16H28V88H8z"/><path fill="#4b8b50" d="M12 40h16V24h20V12h24v16h20v16h12v28H80v16H28V76H12z"/><path fill="#72a65b" d="M28 32h20V20h24v16h16v16H60v12H28z"/><path fill="#9cbd71" d="M36 32h16v-8h12v12H44v8h-8z"/></g></defs><path fill="#a4c77c" d="M0 0h1280v736H0z"/><path fill="#97bc71" d="M0 70h1280v38H0zm0 552h1280v184H0z"/>${tufts}<path fill="#bbd894" d="M112 146h688l136 104-104 270H224L96 408z" opacity=".35"/>${stones}<path fill="#738e66" d="M842 120h226l56 40v76l-60 38H876l-56-40v-76z"/><path fill="#c6c3a0" d="M846 114h212l56 40v76l-56 34H874l-48-34v-70z"/><path fill="#4fa5b3" d="M864 132h184l48 30v60l-48 26H884l-40-28v-54z"/><path fill="#7fc5c8" d="M860 164h220v52l-40 24H888l-28-20z"/><path fill="#c0e5d9" d="M890 170h56v4h-56zm92 52h54v4h-54zm40-66h32v4h-32z"/><path fill="#4d945c" d="M874 210h28v12h-28zm146-24h32v12h-32z"/><path fill="#f7d4c1" d="M1030 182h8v8h-8z"/><g fill="#ad8655" stroke="#795f42" stroke-width="2"><path d="M44 90h1176v10H44zm0 24h1176v8H44z"/>${Array.from({length:25},(_,i)=>`<path d="M${40+i*48} 76h8v60h-8z"/>`).join('')}</g>${trees}<path fill="#739958" d="M0 658h1280v78H0z"/>${[0,112,1020,1140].map((x,i)=>`<use href="#garden-tree" x="${x}" y="${590+i%2*16}"/>`).join('')}<g fill="#f8e9b3">${Array.from({length:28},(_,i)=>`<path d="M${280+i*26} ${608+i%4*12}h4v4h-4z"/>`).join('')}</g></svg>`;
}
